<template><div><UsabilityView v-if="usabilityEnabled"/><Card v-else><section v-if="ordinary&&!error" class="s1-ordinary-wechat"><h2>原生普通微信配置</h2><Alert show-icon>普通微信沿用既有配置维护流程；收付通修改不改变此配置，也不会自动回退到普通微信。</Alert><p>当前库：{{ordinary.state==='CONFIGURED'?'已保存配置':ordinary.state==='NOT_CONFIGURED'?'尚未配置':'配置无法读取，请核查'}}。此摘要不代表真实渠道已验证。</p><p v-if="ordinary.state==='CONFIGURED'">普通商户号：{{ordinary.mchIdMasked||'未填写'}}；小程序 AppID：{{ordinary.mpAppIdMasked||'未填写'}}；API v3 密钥：{{ordinary.apiKey3Configured?'已配置':'未配置'}}；商户私钥：{{ordinary.apiclientKeyConfigured?'已配置':'未配置'}}。</p></section><h2>收付通专属配置</h2><Alert show-icon>当前运行：{{environment||'读取中'}} / {{label(mode)}}。真实渠道出站：{{realOutbound?'已授权':'未授权'}}。</Alert><StatusPanel :error="error" :pending="pending" :busy="busy" :loading="loading" @recover="recover" @retry="retryOriginal" @abandon="abandonPending"/><div class="s1-toolbar"><Button type="primary" :disabled="pending" @click="edit(null)">新增独立配置</Button><Button @click="reload">刷新</Button></div><Table :columns="columns" :data="records" :loading="loading" no-data-text="暂无收付通配置"><template slot="mode" slot-scope="{row}"><Tag :color="row.mode==='MOCK'?'orange':'blue'">{{label(row.mode)}}</Tag></template><template slot="state" slot-scope="{row}">{{row.enabled?'启用':'停用'}} / {{label(row.checkState)}}</template><template slot="action" slot-scope="{row}"><Button size="small" @click="detail(row)">详情</Button><Button size="small" :disabled="pending" @click="edit(row)">编辑</Button></template></Table><Page :total="total" :current="page" :page-size="size" show-total @on-change="page=$event;reload()"/><Drawer v-model="show" title="配置资料" width="760" :mask-closable="false"><Alert v-if="editing">保存修改会停用本配置并重新核验关联资格。渠道账号只做脱敏展示，修改时请重新核对并填写完整账号。</Alert><FieldsForm v-model="form" :fields="fields" :disabled="busy||pending"/><Button type="primary" :loading="busy" :disabled="pending" @click="save">保存配置</Button></Drawer><Drawer v-model="detailShow" title="配置详情与变更历史" width="85"><template v-if="selected"><div class="s1-toolbar"><Button :disabled="pending||busy" @click="command('check')">检查配置</Button><Button :disabled="pending||busy" :type="selected.enabled?'warning':'primary'" @click="command(selected.enabled?'disable':'enable')">{{selected.enabled?'停用':'启用'}}</Button></div><RecordDetail :value="selected"/></template></Drawer></Card></div></template>
<script>import {usabilityEntry} from './usability/enabled';import {leaveGuard} from './usability/entry';import UiView from './usability/ChannelConfigs';import {pageMixin} from './shared';import {s1Read} from '@/api/stage1';import StatusPanel from './StatusPanel';import FieldsForm from './FieldsForm';import RecordDetail from './RecordDetail';const LegacyView = {mixins:[pageMixin],components:{StatusPanel,FieldsForm,RecordDetail},data:()=>({ordinary:null,environment:'',mode:'',realOutbound:false,show:false,detailShow:false,editing:null,form:{},columns:[{title:'名称',key:'name'},{title:'模式',slot:'mode',width:140},{title:'平台商户号',key:'providerMchidMasked'},{title:'支付 AppID',key:'paymentAppIdMasked'},{title:'状态',slot:'state'},{title:'版本',key:'version',width:80},{title:'操作',slot:'action',width:160}]}),computed:{fields(){return [{key:'name',label:'配置名称',required:true,max:60},{key:'mode',label:'模式',type:'select',disabled:!!this.editing,required:true,options:[{value:'MOCK',label:'模拟渠道'},{value:'REAL',label:'真实渠道'}]},{key:'providerMchid',label:'平台服务商商户号',required:true,max:64,help:this.form.mode==='MOCK'?'模拟值必须以 MOCK_ 开头。':'填写已获准使用的真实平台商户号。'},{key:'paymentAppId',label:'支付 AppID',required:true,max:128},...(this.form.mode==='MOCK'?[{key:'mockMaxRateBps',label:'模拟比例上限',type:'integer',max:10000,help:'万分比；未填写保持未知，0 为明确零上限。'}]:[{key:'credentialRef',label:'受控凭据引用',max:64,help:'只填写部署方提供的引用名，不粘贴私钥、密钥或证书。留空保留原引用。'}]),{key:'reason',label:'变更原因',type:'textarea',required:true,max:500}];}},mounted(){if(this.usabilityEnabled)return;this.reload();},methods:{async reload(){const value=await this.load('/channel-configs');if(value){this.ordinary=value.ordinaryWechat;this.environment=value.environment;this.mode=value.authorizedMode;this.realOutbound=value.realOutboundAuthorized;}},edit(row){this.editing=row;this.form={name:row?row.name:'',mode:row?row.mode:'MOCK',providerMchid:'',paymentAppId:'',...(row&&row.mode==='MOCK'?{mockMaxRateBps:row.mockMaxRateBps}:{}),reason:''};this.show=true;},async save(){const body={...this.form};if(this.editing){delete body.mode;body.expectedVersion=this.editing.version;}if(!body.credentialRef)delete body.credentialRef;if(this.form.mode==='REAL')delete body.mockMaxRateBps;else delete body.credentialRef;try{await this.run('/channel-configs'+(this.editing?'/'+this.editing.id+'/draft':''),body,this.editing?'PUT':'POST');this.show=false;await this.reload();}catch(_){}},async detail(row){try{this.selected=await s1Read('/channel-configs/'+row.id);this.detailShow=true;}catch(e){this.error=e.message;}},async command(action){const row=this.selected;const result=await this.reasonAction('/channel-configs/'+row.id+'/'+action,{check:'检查配置并失效旧核验结果',enable:'启用此渠道配置',disable:'停用此配置及相关经营资格'}[action],{expectedVersion:row.version});if(result){await this.detail(row);await this.reload();}}}};LegacyView.mixins.push(usabilityEntry);LegacyView.components={...LegacyView.components,UsabilityView:UiView};LegacyView.beforeRouteLeave=leaveGuard;LegacyView.beforeRouteUpdate=leaveGuard;export default LegacyView;</script><style scoped>.s1-ordinary-wechat{margin-bottom:24px;padding-bottom:20px;border-bottom:1px solid #e8eaec}.s1-ordinary-wechat p{margin:12px 0;line-height:1.7}.s1-toolbar{display:flex;gap:12px;margin:18px 0}.ivu-btn{margin-right:8px}.ivu-page{margin-top:18px}</style>
